contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DEP_BANK c;

    function setUp() public {
        c = new DEP_BANK();
    }

    function _run(uint256 _min, uint256 _dep, uint256 _am) internal {
        _dep = bound(_dep, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(_dep > 0);
        vm.assume(address(this).balance >= _dep);
        try c.SetMinSum(_min) {} catch { return; }
        try c.Deposit{value: _dep}() {} catch { return; }
        uint256 balBefore;
        try c.balances(address(this)) returns (uint256 __r) { balBefore = __r; } catch { return; }
        try c.Collect(_am) {} catch { return; }
        uint256 balAfter;
        try c.balances(address(this)) returns (uint256 __r) { balAfter = __r; } catch { return; }
        assertTrue(balAfter <= balBefore &&
               (balBefore < c.MinSum() || balBefore < _am || balAfter == balBefore - _am));
    }

    function testFuzz_run(uint256 _min, uint256 _dep, uint256 _am) public {
        _run(_min, _dep, _am);
    }

    receive() external payable {}

    fallback() external payable {}
